create function app_private.session_context() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin
 if app_private.current_profile() is null then raise exception 'forbidden' using errcode='42501'; end if;
 return jsonb_build_object('platform_admin',app_private.is_platform_admin(),'staff',(select coalesce(jsonb_agg(jsonb_build_object('organization_id',organization_id,'id',id)),'[]'::jsonb) from public.staff where profile_id=app_private.current_profile() and active)); end $$;
create function app_private.create_organization_for_email(p_name text,p_slug text,p_timezone text,p_currency text,p_owner_email text) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_owner uuid; begin
 if not app_private.is_platform_admin() then raise exception 'forbidden' using errcode='42501'; end if;
 select id into v_owner from auth.users where lower(email)=lower(p_owner_email);
 return app_private.create_organization(p_name,p_slug,p_timezone,p_currency,v_owner); end $$;
create function app_private.list_agenda(p_org uuid,p_branch uuid,p_staff uuid,p_service uuid,p_status text,p_from timestamptz,p_to timestamptz) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_result jsonb; begin
 if not app_private.can_access_branch(p_org,p_branch) or p_to<=p_from or p_to-p_from>interval '8 days' or (p_staff is not null and not app_private.can_read_staff(p_org,p_staff)) or (p_status is not null and p_status not in ('scheduled','confirmed','checked_in','in_service','completed','cancelled','no_show','rescheduled')) then raise exception 'forbidden' using errcode='42501'; end if;
 with rows as (
 select a.id,a.branch_id,a.customer_id,a.staff_id,a.starts_at,a.ends_at,a.duration_minutes,a.status,a.currency,a.price_minor,c.name as customer_name,s.name as staff_name,
 (select coalesce(jsonb_agg(jsonb_build_object('id',aps.service_id,'name',aps.name_snapshot)),'[]'::jsonb) from public.appointment_services aps where aps.organization_id=p_org and aps.appointment_id=a.id) as services
 from public.appointments a join public.customers c on c.organization_id=a.organization_id and c.id=a.customer_id join public.staff s on s.organization_id=a.organization_id and s.id=a.staff_id
 where a.organization_id=p_org and a.branch_id=p_branch and a.starts_at<p_to and a.ends_at>p_from and app_private.can_read_appointment(p_org,a.id) and (p_staff is null or a.staff_id=p_staff) and (p_status is null or a.status=p_status) and (p_service is null or exists(select 1 from public.appointment_services aps where aps.organization_id=p_org and aps.appointment_id=a.id and aps.service_id=p_service)) order by a.starts_at,a.id limit 2001
 )
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(q) order by q.starts_at,q.id) from (select * from rows limit 2000) q),'[]'::jsonb),'has_more',(select count(*)>2000 from rows)) into v_result; return v_result; end $$;
create function app_private.appointment_detail(p_org uuid,p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_result jsonb; begin
 if not app_private.can_read_appointment(p_org,p_id) then raise exception 'forbidden' using errcode='42501'; end if;
 select jsonb_build_object('id',a.id,'branch_id',a.branch_id,'customer_id',a.customer_id,'staff_id',a.staff_id,'starts_at',a.starts_at,'ends_at',a.ends_at,'duration_minutes',a.duration_minutes,'status',a.status,'currency',a.currency,'price_minor',a.price_minor,'customer_name',c.name,'staff_name',s.name,'services',(select coalesce(jsonb_agg(jsonb_build_object('id',service_id,'name',name_snapshot)),'[]'::jsonb) from public.appointment_services where organization_id=p_org and appointment_id=p_id)) into v_result
 from public.appointments a join public.customers c on c.organization_id=a.organization_id and c.id=a.customer_id join public.staff s on s.id=a.staff_id where a.organization_id=p_org and a.id=p_id;
 return v_result; end $$;
create function app_private.goal_progress(p_org uuid,p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare g public.goals; v_dashboard jsonb; v_value numeric; v_tz text; begin
 select * into g from public.goals where organization_id=p_org and id=p_id;
 if g.id is null or not (app_private.has_org_role(p_org,array['organization_owner']) or (app_private.has_org_role(p_org,array['manager']) and g.branch_id is not null and app_private.can_access_branch(p_org,g.branch_id)) or g.staff_id=app_private.current_staff_id(p_org)) then raise exception 'forbidden' using errcode='42501'; end if;
 select coalesce((select timezone from public.branches where id=g.branch_id),o.timezone) into v_tz from public.organizations o where id=p_org;
 if g.starts_at>now() then return jsonb_build_object('value',0,'progress_percent',0); end if;
 v_dashboard:=app_private.dashboard(p_org,g.branch_id,g.staff_id,(g.starts_at at time zone v_tz)::date,(least(g.ends_at-interval '1 microsecond',now()) at time zone v_tz)::date);
 v_value:=case g.metric when 'services_completed' then (v_dashboard->'totals'->>'services_completed')::numeric when 'appointments_completed' then (v_dashboard->'totals'->>'completed')::numeric when 'production_value' then (v_dashboard->'totals'->>'production_value_minor')::numeric when 'utilization' then (v_dashboard->'totals'->>'utilization')::numeric when 'rebookings' then (v_dashboard->'totals'->>'rebookings')::numeric end;
 return jsonb_build_object('value',v_value,'progress_percent',case when v_value is null then null else round(v_value/g.target_value*100,1) end); end $$;
create function public.session_context() returns jsonb language sql security invoker set search_path='' as $$ select app_private.session_context() $$; revoke all on function public.session_context(),app_private.session_context() from public,anon,authenticated; grant execute on function public.session_context(),app_private.session_context() to authenticated;
create function public.create_organization_for_email(p_name text,p_slug text,p_timezone text,p_currency text,p_owner_email text) returns jsonb language sql security invoker set search_path='' as $$ select app_private.create_organization_for_email($1,$2,$3,$4,$5) $$; revoke all on function public.create_organization_for_email(text,text,text,text,text),app_private.create_organization_for_email(text,text,text,text,text) from public,anon,authenticated; grant execute on function public.create_organization_for_email(text,text,text,text,text),app_private.create_organization_for_email(text,text,text,text,text) to authenticated;
create function public.list_agenda(p_org uuid,p_branch uuid,p_staff uuid,p_service uuid,p_status text,p_from timestamptz,p_to timestamptz) returns jsonb language sql security invoker set search_path='' as $$ select app_private.list_agenda($1,$2,$3,$4,$5,$6,$7) $$; revoke all on function public.list_agenda(uuid,uuid,uuid,uuid,text,timestamptz,timestamptz),app_private.list_agenda(uuid,uuid,uuid,uuid,text,timestamptz,timestamptz) from public,anon,authenticated; grant execute on function public.list_agenda(uuid,uuid,uuid,uuid,text,timestamptz,timestamptz),app_private.list_agenda(uuid,uuid,uuid,uuid,text,timestamptz,timestamptz) to authenticated;
create function public.appointment_detail(p_org uuid,p_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select app_private.appointment_detail($1,$2) $$; revoke all on function public.appointment_detail(uuid,uuid),app_private.appointment_detail(uuid,uuid) from public,anon,authenticated; grant execute on function public.appointment_detail(uuid,uuid),app_private.appointment_detail(uuid,uuid) to authenticated;
create function public.goal_progress(p_org uuid,p_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select app_private.goal_progress($1,$2) $$; revoke all on function public.goal_progress(uuid,uuid),app_private.goal_progress(uuid,uuid) from public,anon,authenticated; grant execute on function public.goal_progress(uuid,uuid),app_private.goal_progress(uuid,uuid) to authenticated;
